+    private static int computeHighOrderMultiplier(int patternLength) {
+        int highOrderMultiplier = 1;
+        for (int i = 0; i < patternLength - 1; i++) {
+            highOrderMultiplier = (highOrderMultiplier * RADIX) % MODULUS;
+        }
+        return highOrderMultiplier;
+    }
